import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_SIZE": 32},
        ),
    ],
    key=["output_length", "kernel_size"],
)
@triton.jit
def avg_pool1d_kernel(
    input_ptr,
    output_ptr,
    input_length,
    output_length,
    kernel_size,
    stride,
    padding,
    stride_b,
    stride_c,
    stride_l,
    out_stride_b,
    out_stride_c,
    out_stride_l,
    BLOCK_SIZE: tl.constexpr,
):
    pid_bc = tl.program_id(0)
    pid_l = tl.program_id(1)

    offs = pid_l * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offs < output_length

    acc = tl.zeros((BLOCK_SIZE,), dtype=tl.float32)

    for k in range(kernel_size):
        inp_pos = offs * stride - padding + k
        inp_mask = mask & (inp_pos >= 0) & (inp_pos < input_length)
        inp_ptr = input_ptr + pid_bc.to(tl.int64) * stride_c + inp_pos * stride_l
        val = tl.load(inp_ptr, mask=inp_mask, other=0.0).to(tl.float32)
        acc += val

    inv_kernel_size = 1.0 / kernel_size
    acc = acc * inv_kernel_size

    out_ptr = output_ptr + pid_bc.to(tl.int64) * out_stride_c + offs * out_stride_l
    tl.store(out_ptr, acc.to(tl.bfloat16), mask=mask)


def kernel_function(
    x: torch.Tensor, kernel_size: int, stride: int, padding: int
) -> torch.Tensor:
    batch_size, in_channels, input_length = x.shape
    output_length = (input_length + 2 * padding - kernel_size) // stride + 1

    if x.dtype != torch.bfloat16:
        x = x.to(torch.bfloat16)
    x = x.contiguous()

    output = torch.empty(
        (batch_size, in_channels, output_length),
        device=x.device,
        dtype=torch.bfloat16,
    )

    total_bc = batch_size * in_channels

    x_flat = x.view(total_bc, input_length)
    out_flat = output.view(total_bc, output_length)

    grid = lambda META: (total_bc, triton.cdiv(output_length, META["BLOCK_SIZE"]))

    avg_pool1d_kernel[grid](
        x_flat,
        out_flat,
        input_length,
        output_length,
        kernel_size,
        stride,
        padding,
        x_flat.stride(0),
        x_flat.stride(0),
        x_flat.stride(1),
        out_flat.stride(0),
        out_flat.stride(0),
        out_flat.stride(1),
    )

    return output


batch_size = 64
in_channels = 128
input_length = 65536
kernel_size = 8
stride = 1
padding = 4


class Model(nn.Module):
    def __init__(self, kernel_size: int, stride: int = 1, padding: int = 0):
        super(Model, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return kernel_function(x, self.kernel_size, self.stride, self.padding)


def get_inputs():
    x = torch.rand(batch_size, in_channels, input_length, dtype=torch.bfloat16)
    return [x]


def get_init_inputs():
    return [kernel_size, stride, padding]
